package api.hbm.entity;
import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.resources.*;import net.minecraft.core.registries.Registries;import net.minecraft.util.Mth;import net.minecraft.world.entity.Entity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;
/** Source shared detection entry; native dimension identity replaces obsolete numeric dimension IDs. */
public final class RadarEntry{public String unlocalizedName;public int blipLevel,posX,posY,posZ,entityID;public ResourceKey<Level> dim;public boolean redstone;public RadarEntry(){}public RadarEntry(String name,int type,Entity entity,boolean redstone){unlocalizedName=name;blipLevel=type;posX=Mth.floor(entity.getX());posY=Mth.floor(entity.getY());posZ=Mth.floor(entity.getZ());dim=entity.level().dimension();entityID=entity.getId();this.redstone=redstone;}public RadarEntry(IRadarDetectableNT d,Entity e,boolean redstone){this(d.getUnlocalizedName(),d.getBlipLevel(),e,redstone);}public RadarEntry(IRadarDetectable d,Entity e){this(d.getTargetType().name,d.getTargetType().ordinal(),e,e.getDeltaMovement().y<0);}public RadarEntry(Player player){this(player.getDisplayName().getString(),IRadarDetectableNT.PLAYER,player,true);}public void write(RegistryFriendlyByteBuf b){b.writeUtf(unlocalizedName);b.writeShort(blipLevel);b.writeInt(posX);b.writeInt(posY);b.writeInt(posZ);b.writeResourceKey(dim);b.writeInt(entityID);}public static RadarEntry read(RegistryFriendlyByteBuf b){var e=new RadarEntry();e.unlocalizedName=b.readUtf();e.blipLevel=b.readShort();e.posX=b.readInt();e.posY=b.readInt();e.posZ=b.readInt();e.dim=b.readResourceKey(Registries.DIMENSION);e.entityID=b.readInt();return e;}}
